Section CANSEC1. Context {rc : runConstT}.
Lemma su_disjoint : forall L W A k,
  sec_untouched L W -> Forall (fun iv => fst iv < snd iv) W -> 0 < k ->
  (forall a, A <= a < A + k -> aknown L a -> False) ->
  disjoint_from W A k.
