(* [comment removed for export] *)
Lemma clear_free_shadow : forall x,
  (AIMG_HI <= x < KLS \/ K_HIGH_MEM <= x < ATOP) ->
  Forall (fun iv => ~ (fst iv <= x < snd iv)) (astartup_hulls L) ->
